with dim_totals as (select d.status as order_status, src.status as shipment_status, count(*) as num_rows, min(src.cost) as min_cost, grouping_id() as grouping_level from shipments src join orders d on src.order_id = d.id group by grouping sets ((d.status, src.status), (d.status), ())) select order_status, shipment_status, num_rows, min_cost from dim_totals order by order_status nulls first
